<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,allPages,fmt} from '../api'
import {useWorkspace} from '../store'
import {jobNames} from '../platform'
import Icon from '../components/Icon.vue'
import Status from '../components/Status.vue'
const route=useRoute(),router=useRouter(),store=useWorkspace(),chat=computed(()=>route.path==='/chat'),resources=ref<any[]>([]),entities=ref<any[]>([]),cases=ref<any[]>([]),history=ref<any[]>([]),text=ref(''),operation=ref('generate'),mode=ref('simulation'),target=ref('ui_case'),uiPlatform=ref<'app'|'web'>('app'),model=ref<number|null>(null),agent=ref<number|null>(null),skills=ref<number[]>([]),source=ref<number|null>(null),knowledge=ref<number[]>([]),caseIds=ref<number[]>([]),relatedEntityIds=ref<number[]>([]),prompt=ref<number|null>(null),template=ref<number|null>(null),strategy=ref<number|null>(null),count=ref(5),autoApply=ref(true),busy=ref(false),current=ref<any>(null),toolDialog=ref(false),toolResource=ref<number|null>(null),toolName=ref(''),argumentsText=ref('{}'),specialty=ref('完整性、歧义、异常路径、边界与权限'),sourceJob=ref<number|null>(null),failureCase=ref<number|null>(null),focusModule=ref('')
const operations=['generate','design','optimize','review','split','analyze']
const graphStages=[{name:'上下文',progress:15},{name:'功能分析',progress:30},{name:'生成',progress:50},{name:'检查',progress:70},{name:'优化',progress:88},{name:'校验',progress:96}]
const active=computed(()=>current.value&&['queued','running'].includes(current.value.status))
const composeTitle=computed(()=>{
  if(operation.value==='generate')return target.value==='api'?'先提取接口清单，再按接口名称生成用例':'先分析需求功能，再按功能生成用例'
  return {design:'先完整拆解需求，再生成指定模块的单校验点用例',optimize:target.value==='api'?'编辑并修复接口、环境与关联测试配置':'让已有用例更完整',review:'发现需求中的遗漏与歧义',split:'将复杂需求拆分为可测试单元',analyze:'分析失败证据，给出修复建议'}[operation.value]||''
})
watch(operation,value=>{if(value==='design')target.value='ui_case'})
watch(mode,value=>{if(value==='live'&&!resources.value.some(r=>r.id===model.value&&r.mode==='live'))model.value=resources.value.find(r=>r.kind==='model'&&r.enabled&&r.mode==='live'&&r.settings?.provider_type!=='h2o_decisions')?.id||null})
const moduleOptions=computed(()=>{const doc=entities.value.find(e=>e.id===source.value);const body=doc?.content||text.value;return [...body.matchAll(/^###\s+(.+)$/gm)].map((m:any)=>m[1].replace(/^\d+(?:\.\d+)*\s*/,''))})
watch(moduleOptions,(options)=>{if(operation.value==='design'&&options.length&&!options.includes(focusModule.value))focusModule.value=options.find(x=>x.includes('登录'))||options[0]})
async function init(){if(!store.projectId)return;[resources.value,entities.value,cases.value]=await Promise.all([allPages('resources/',{project:store.projectId}),allPages('entities/',{project:store.projectId}),allPages('assets/',{project:store.projectId,kind:'case'})]);operation.value=String(route.query.operation||'generate');source.value=route.query.entity?Number(route.query.entity):null;target.value=String(route.query.target||'ui_case');if(target.value==='case'||target.value==='ui')target.value='ui_case';uiPlatform.value=route.query.platform==='web'?'web':'app';const requestedSkill=Number(route.query.skill);skills.value=requestedSkill&&resources.value.some(r=>r.id===requestedSkill&&r.kind==='skill')?[requestedSkill]:[];sourceJob.value=route.query.job?Number(route.query.job):null;failureCase.value=route.query.case_id?Number(route.query.case_id):null;relatedEntityIds.value=[];const apiCase=entities.value.find(item=>item.id===source.value&&item.kind==='api');if(operation.value==='optimize'&&target.value==='api'&&apiCase){const ids=[...(apiCase.config?.function_ids||[]),...(apiCase.config?.assertions||[]).filter((rule:any)=>rule.type==='db_equals').map((rule:any)=>rule.database_id)].filter((id:any)=>Number.isInteger(id));relatedEntityIds.value=[...new Set(ids)]}if(operation.value==='optimize'&&target.value==='api'){mode.value='live';model.value=resources.value.find(r=>r.kind==='model'&&r.enabled&&r.mode==='live'&&r.settings?.provider_type!=='h2o_decisions')?.id||null}if(operation.value==='analyze'&&sourceJob.value){mode.value='live';model.value=resources.value.find(r=>r.kind==='model'&&r.enabled&&r.mode==='live'&&r.settings?.provider_type!=='h2o_decisions')?.id||null;try{const response=await api.get('jobs/'+sourceJob.value+'/');const failedCase=response.data.payload.snapshots?.find((item:any)=>item.id===failureCase.value);if(failedCase?.config?.platform)uiPlatform.value=failedCase.config.platform}catch{}text.value='请基于关联用例的失败步骤、断言、响应和执行日志分析根因；若确属用例配置问题，请给出最小范围的完整配置修复。'}if(operation.value==='optimize'&&target.value==='api'&&!text.value)text.value='检查并修复接口配置：请求参数与 Header、环境变量引用、数据库校验、前后置公共函数、断言规则和变量依赖。只修改有证据支持的字段，保留其他有效配置。';if(operation.value==='design'){count.value=40;autoApply.value=false}current.value=null;history.value=[];if(chat.value)history.value=(await api.get('jobs/',{params:{project:store.projectId,kind:'chat'}})).data.results.reverse()}
watch(()=>[store.projectId,route.path,route.query.entity,route.query.operation,route.query.target,route.query.platform,route.query.skill,route.query.job,route.query.case_id],init,{immediate:true})
function jobPayload(){return {text:text.value,entity_id:source.value,case_ids:caseIds.value,related_entity_ids:operation.value==='optimize'&&target.value==='api'?relatedEntityIds.value:[],skill_ids:skills.value,model_id:model.value,agent_id:agent.value,knowledge_ids:knowledge.value,prompt_id:prompt.value,template_id:template.value,strategy_id:strategy.value,...(operation.value!=='design'?{count:count.value}:{}),target_kind:target.value,ui_platform:uiPlatform.value,auto_apply:autoApply.value,specialty:specialty.value,focus_module:focusModule.value,source_job:operation.value==='analyze'?sourceJob.value:null,...(operation.value==='analyze'&&failureCase.value?{failure_case_id:failureCase.value}:{}),messages:chat.value?history.value.slice(-8).map(j=>({question:j.payload.text,answer:j.result.output?.answer||''})):[]}}
function jobName(){const prefix=chat.value?'对话 · ':jobNames[operation.value]+' · ';return prefix+(text.value.slice(0,30)||entities.value.find(x=>x.id===source.value)?.name||'测试资产')}
async function submit(){
  if(operation.value==='design'&&!focusModule.value.trim()){ElMessage.warning('请选择目标模块');return}if(operation.value==='optimize'&&target.value==='api'&&(!source.value||!entities.value.some(item=>item.id===source.value&&item.kind==='api'))){ElMessage.warning('请选择要编辑的接口用例');return}
  if(mode.value==='live'&&!resources.value.some(r=>r.id===model.value&&r.kind==='model'&&r.enabled&&r.mode==='live')){ElMessage.warning('请先在模型管理中验证连接，并选择可用的真实模型');return}
  if(!text.value.trim()&&!source.value&&!caseIds.value.length&&!sourceJob.value){ElMessage.warning('请输入需求、选择文档或已有用例');return}
  busy.value=true
  try{
    const {data}=await api.post('jobs/',{project:store.projectId,kind:chat.value?'chat':operation.value,name:jobName(),mode:mode.value,payload:jobPayload()})
    current.value=data
    if(chat.value){history.value.push(data);text.value=''}
    ElMessage.success('任务已提交，后台开始处理')
  }finally{busy.value=false}
}
async function poll(){if(!active.value)return;try{const {data}=await api.get(`jobs/${current.value.id}/`);current.value=data;const i=history.value.findIndex(j=>j.id===data.id);if(i>=0)history.value[i]=data}catch{}}
const timer=setInterval(poll,2000);onUnmounted(()=>clearInterval(timer))
async function apply(){await api.post(`jobs/${current.value.id}/apply/`);current.value=(await api.get(`jobs/${current.value.id}/`)).data;ElMessage.success('已写入测试资产')}
async function repairRetry(){busy.value=true;try{const {data}=await api.post(`jobs/${current.value.id}/repair_retry/`);ElMessage.success(`用例已修复，重试任务 #${data.job.id} 已排队`);router.push('/tasks/'+data.job.id)}finally{busy.value=false}}
async function toolCall(){let args;try{args=JSON.parse(argumentsText.value)}catch{ElMessage.warning('工具参数必须为 JSON');return}const {data}=await api.post('jobs/',{project:store.projectId,kind:'mcp',mode:mode.value,name:'MCP · '+toolName.value,payload:{resource_id:toolResource.value,tool:toolName.value,arguments:args}});toolDialog.value=false;router.push('/tasks/'+data.id)}
</script>
<template><div><div class="page-heading"><div><div class="heading-eyebrow">{{chat?'PROJECT AGENT':'INTELLIGENT TEST DESIGN'}}</div><h1>{{chat?'Agent 对话':'AI 智能工作室'}}<span class="heading-tag">LangGraph</span></h1><p>{{chat?'在项目上下文中分析测试问题，关联知识与受控工具。':'让需求、知识与团队规范汇聚为完整的测试用例。'}}</p></div><el-button @click="router.push('/templates')"><Icon name="Setting"/>{{ $t('管理模板与策略') }}</el-button></div>
<div class="studio-layout"><aside class="panel studio-settings"><h3>{{ $t('上下文与能力配置') }}</h3><el-form label-position="top"><el-form-item :label="$t('执行模式')"><el-radio-group v-model="mode"><el-radio-button value="simulation" :disabled="(operation==='analyze'&&!!sourceJob)||(operation==='optimize'&&target==='api')">{{ $t('模拟') }}</el-radio-button><el-radio-button value="live">{{ $t('真实模型') }}</el-radio-button></el-radio-group></el-form-item><el-form-item :label="$t('语言模型')"><el-select v-model="model" clearable :value-on-clear="null" :placeholder="mode==='live'?'选择已验证连接的模型':$t('选择已配置模型')"><el-option v-for="r in resources.filter(r=>r.kind==='model'&&(mode==='simulation'||r.mode==='live'))" :key="r.id" :label="r.name+(r.mode!=='live'?'（未验证）':'')" :value="r.id"/></el-select></el-form-item><el-form-item :label="$t('Agent / 系统指令')"><el-select v-model="agent" clearable :value-on-clear="null" :placeholder="$t('默认测试工程师')"><el-option v-for="r in resources.filter(r=>r.kind==='agent')" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="Skills（留空自动匹配）"><el-select v-model="skills" multiple filterable clearable placeholder="按任务类型自动选择"><el-option v-for="r in resources.filter(r=>r.kind==='skill'&&r.enabled)" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item :label="$t('需求 / 接口 / UI 定义')"><el-select v-model="source" filterable clearable :value-on-clear="null" :placeholder="$t('选择上下文文档')"><el-option v-for="e in entities.filter(e=>['requirement','api','ui_case','knowledge_document'].includes(e.kind))" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><el-form-item :label="$t('知识库上下文')"><el-select v-model="knowledge" multiple clearable :placeholder="$t('选择项目知识库')"><el-option v-for="e in entities.filter(e=>e.kind==='knowledge')" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><template v-if="!chat"><el-form-item :label="$t('已有用例（优化 / 上下文）')"><el-select v-model="caseIds" multiple filterable :placeholder="$t('选择用例')"><el-option v-for="c in cases" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item :label="$t('Prompt 模板')"><el-select v-model="prompt" clearable :value-on-clear="null"><el-option v-for="e in entities.filter(e=>e.kind==='prompt')" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><el-form-item :label="$t('用例模板')"><el-select v-model="template" clearable :value-on-clear="null"><el-option v-for="e in entities.filter(e=>e.kind==='case_template')" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><el-form-item :label="$t('生成策略')"><el-select v-model="strategy" clearable :value-on-clear="null"><el-option v-for="e in entities.filter(e=>e.kind==='strategy')" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item></template></el-form><div class="helper">{{mode==='simulation'?'模拟模式使用规则示例，不消耗模型 Token。':'真实模型会接收选中的文档与知识上下文；需配置凭据与目标白名单。'}}</div></aside>
<section class="studio-main"><div v-if="!chat" class="panel studio-compose"><div class="operation-tabs"><button v-for="op in operations" :key="op" :class="{selected:operation===op}" :disabled="!!sourceJob&&op!=='analyze'" @click="operation=op">{{$t(jobNames[op])}}</button></div><h2>{{composeTitle}}</h2><el-alert v-if="operation==='analyze'&&sourceJob" title="已关联真实执行失败记录。真实模型会收到该用例配置和脱敏后的失败证据；只有判定为用例问题且提供有效修复配置时，才允许应用并重新执行。" type="warning" :closable="false"/><el-input v-model="text" type="textarea" :rows="7" :placeholder="operation==='optimize'&&target==='api'?'描述要修复的接口配置，例如：补充分页参数、校正断言、修复变量依赖或调整环境 Header':$t('描述业务流程、测试范围、边界条件和验收标准；也可以在左侧选择需求文档。')"/><el-form v-if="operation==='optimize'&&target==='api'" label-position="top" style="margin-top:16px"><el-form-item label="纳入 AI 检查的关联配置"><el-select v-model="relatedEntityIds" multiple filterable collapse-tags collapse-tags-tooltip placeholder="已自动包含用例引用的公共函数和数据库，可补充环境"><el-option v-for="item in entities.filter((entity:any)=>['environment','database','function'].includes(entity.kind))" :key="item.id" :value="item.id" :label="`${item.name} · ${item.kind==='environment'?'环境':item.kind==='database'?'数据库':'公共函数'}`"/></el-select></el-form-item><p class="helper">AI 可检查并提出接口参数、Header、变量、断言、前后置函数，以及所选环境/数据库/公共函数的修复。脚本只支持平台声明式函数，密钥保留服务端引用；结果通过配置校验和版本冲突检查后写入。</p></el-form><el-form v-if="operation==='design'" label-position="top" style="margin-top:16px"><el-form-item label="指定生成用例的模块"><el-select v-if="moduleOptions.length" v-model="focusModule" filterable allow-create default-first-option placeholder="选择需求文档中的模块"><el-option label="全部模块" value="全部模块"/><el-option v-for="name in moduleOptions" :key="name" :label="name" :value="name"/></el-select><el-input v-else v-model="focusModule" placeholder="例如：注册/登录"/></el-form-item><p class="helper">第一阶段拆解全文各功能节点及规则；第二阶段只为所选模块生成用例。模拟模式只保留原文结构，不生成真实用例。</p></el-form><div class="generation-controls"><el-select v-model="target" style="width:155px" :disabled="operation==='design'||(operation==='analyze'&&!!sourceJob)"><el-option :label="$t('接口自动化用例')" value="api"/><el-option :label="$t('UI 自动化用例')" value="ui_case"/></el-select><el-select v-if="target==='ui_case'" v-model="uiPlatform" :disabled="operation==='analyze'&&!!sourceJob" style="width:130px"><el-option label="App 用例" value="app"/><el-option label="Web 用例" value="web"/></el-select><el-input-number v-if="operation!=='design'" v-model="count" :min="1" :max="30"/><span v-else class="helper">按需求规则完整生成，不限制数量</span><el-checkbox v-model="autoApply">{{ $t('自动写入资产') }}</el-checkbox></div><el-input v-if="operation==='review'" v-model="specialty" :placeholder="$t('专项分析关注点')"/><div class="compose-footer"><span><Icon name="Lock" :size="14"/>{{ $t('项目上下文隔离 · 结果可追溯') }}</span><el-button type="primary" :disabled="!store.canEdit||active||(operation==='analyze'&&sourceJob&&!model)" :loading="busy" @click="submit"><Icon name="MagicStick"/>开始{{jobNames[operation]}}</el-button></div></div>
<div v-else class="panel chat-panel"><div v-if="!history.length" class="chat-welcome"><span class="large-icon violet"><Icon name="Cpu" :size="28"/></span><h2>{{ $t('一起把测试想清楚') }}</h2><p>{{ $t('分析需求、完善用例，或结合执行结果定位失败原因。') }}</p></div><div v-for="j in history" :key="j.id" class="chat-turn"><div class="chat-question">{{j.payload.text}}</div><div class="chat-answer"><span class="mini-badge">{{j.mode==='live'?'真实模型':'模拟模式'}} · {{j.usage.total_tokens||0}} tokens</span><p>{{j.result.output?.answer||j.result.error||(j.status==='completed'?JSON.stringify(j.result.output):'正在检索与分析…')}}</p><ul v-if="j.result.output?.suggestions"><li v-for="s in j.result.output.suggestions" :key="s">{{s}}</li></ul><el-button link @click="router.push('/tasks/'+j.id)">{{ $t('查看流程与引用') }}</el-button></div></div><div class="chat-composer"><el-input v-model="text" type="textarea" :rows="3" :placeholder="$t('输入项目测试问题…')"/><div class="compose-footer"><el-button @click="toolDialog=true"><Icon name="Link"/>{{ $t('MCP 工具') }}</el-button><el-button type="primary" :disabled="!store.canEdit||active" :loading="busy" @click="submit">{{ $t('发送') }}</el-button></div></div></div>
<section v-if="current&&!chat" class="panel generation-result"><div class="panel-heading"><h3>{{ $t('生成过程与结果') }}</h3><div class="inline-actions"><span class="mode-pill">{{current.mode==='live'?'真实模型':'模拟模式'}}</span><Status :value="current.status"/><el-button link @click="router.push('/tasks/'+current.id)">{{ $t('完整记录') }}</el-button></div></div><div class="graph-stages"><span v-for="stage in graphStages" :key="stage.name" :class="{done:current.progress>=stage.progress}"><Icon :name="current.progress>=stage.progress?'CircleCheck':'Clock'" :size="15"/>{{stage.name}}</span></div><el-progress :percentage="current.progress"/><p v-if="current.result.error" class="text-red">{{current.result.error}}</p><div v-if="current.kind==='analyze'&&current.result.output?.classification" class="generated-case"><el-tag :type="current.result.output.classification==='test_case_issue'?'warning':current.result.output.classification==='product_bug'?'danger':'info'">{{({test_case_issue:'用例问题',product_bug:'疑似产品缺陷',environment_issue:'环境问题',inconclusive:'证据不足'} as any)[current.result.output.classification]}}</el-tag><p>{{current.result.output.summary}}</p><h4 v-if="current.result.output.evidence?.length">分析证据</h4><ul><li v-for="(evidence,index) in current.result.output.evidence" :key="index">{{evidence}}</li></ul><p v-if="current.mode!=='live'||current.result.output.mode==='simulation'" class="helper">模拟分析不会修改用例或发起重跑。</p><template v-if="current.result.output.repair_config"><h4>建议修复配置</h4><pre class="json-result">{{JSON.stringify(current.result.output.repair_config,null,2)}}</pre><el-button v-if="current.status==='completed'&&current.mode==='live'&&current.result.output.classification==='test_case_issue'&&store.canEdit" type="primary" :loading="busy" @click="repairRetry">应用修复并继续执行</el-button></template><p v-else-if="current.result.output.classification!=='test_case_issue'" class="helper">分析认为问题不在用例配置中，因此不会修改用例或自动重试。</p><p v-else class="helper">虽然判定为用例问题，但模型未提供完整且可校验的修复配置，请人工调整用例后重新执行。</p></div><div v-if="current.result.output?.breakdown?.length"><h3>需求功能拆解</h3><el-collapse><el-collapse-item v-for="m in current.result.output.breakdown" :key="m.id" :title="`${m.name} · ${m.functions.length} 个功能节点`"><div v-for="f in m.functions" :key="f.id" class="generated-case"><h4>{{f.name}} <small>{{f.id}}</small></h4><p v-for="(label,key) in {preconditions:'前置条件',flow:'操作流程',validation:'校验规则',errors:'异常提示',special:'特殊逻辑',open_questions:'待确认'}" :key="key" v-show="f[key]?.length"><strong>{{label}}：</strong>{{f[key]?.join('；')}}</p><el-collapse><el-collapse-item title="查看需求原文"><pre class="json-result">{{f.source_text}}</pre></el-collapse-item></el-collapse></div></el-collapse-item></el-collapse><p v-if="current.result.output.notice" class="helper">{{current.result.output.notice}}</p><a :href="`/api/jobs/${current.id}/export/?download=markdown`" class="button-link">导出 Markdown 测试文档</a></div><div v-if="current.result.output?.features?.length" class="info-banner"><Icon name="Collection"/><div><strong>已识别功能</strong><p>{{current.result.output.features.map((f:any)=>f.name).join('、')}}</p></div></div><div v-for="(c,i) in current.result.output?.cases||[]" :key="i" class="generated-case"><h3>{{c.name}}</h3><p v-if="c.feature" class="helper">所属功能：{{c.feature}} · {{c.scenario||''}} <span v-if="c.case_id">· {{c.case_id}}</span></p><p v-if="c.preconditions" class="helper">前置条件：{{c.preconditions}}</p><ol v-if="c.steps"><li v-for="(s,n) in c.steps" :key="n"><b>{{s.action}}</b><span>{{s.expected}}</span></li></ol><pre v-else class="json-result">{{JSON.stringify(c.config,null,2)}}</pre></div><div v-if="current.result.output?.related_configs?.length" class="generated-case"><h3>关联配置变更</h3><div v-for="patch in current.result.output.related_configs" :key="patch.id"><h4>{{entities.find((item:any)=>item.id===patch.id)?.name||('配置 #'+patch.id)}}</h4><pre class="json-result">{{JSON.stringify(patch.config,null,2)}}</pre></div></div><pre v-if="current.result.output&&!current.result.output.cases&&current.kind!=='analyze'" class="json-result">{{JSON.stringify(current.result.output,null,2)}}</pre><div v-if="current.status==='completed'" class="compose-footer"><span>Token：{{current.usage.total_tokens||0}} · 调用：{{current.usage.calls||0}} 次</span><el-button v-if="!current.applied&&(current.result.output?.cases?.length||current.result.output?.requirements)" type="primary" @click="apply">{{ $t('应用到测试资产') }}</el-button><span v-else-if="current.applied" class="text-green">{{ $t('已自动写入测试资产') }}</span></div><p v-if="current.result.apply_error" class="text-red">{{current.result.apply_error}}</p></section></section></div>
<el-dialog v-model="toolDialog" :title="$t('提交 MCP 工具调用')" width="600px"><el-form label-position="top"><el-form-item :label="$t('远程 MCP 服务')"><el-select v-model="toolResource"><el-option v-for="r in resources.filter(x=>x.kind==='mcp')" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item :label="$t('工具名称')"><el-input v-model="toolName" :placeholder="$t('连接测试后可在任务结果中查看 tools/list')"/></el-form-item><el-form-item :label="$t('参数 JSON')"><el-input v-model="argumentsText" type="textarea" :rows="7"/></el-form-item></el-form><p class="helper">{{ $t('真实调用将进入待审批状态，由项目管理员在任务中心批准具体工具与参数后才执行。') }}</p><template #footer><el-button @click="toolDialog=false">{{ $t('取消') }}</el-button><el-button type="primary" @click="toolCall">{{ $t('提交审批') }}</el-button></template></el-dialog>
</div></template>
